276	func logCheckpointMigrationSkip(ctx context.Context, checkpointID id.CheckpointID, reason string, err error) {
277		logging.Info(ctx, "checkpoint migration skipped",
278			slog.String("checkpoint_id", string(checkpointID)),
279			slog.String("reason", reason),
280			slog.String("error", err.Error()),
281		)
282	}
