284	func sortMigratableCheckpoints(checkpoints []checkpoint.CommittedInfo) {
285		sort.SliceStable(checkpoints, func(i, j int) bool {
286			left := checkpoints[i].CreatedAt
287			right := checkpoints[j].CreatedAt
288			switch {
289			case left.IsZero() && right.IsZero():
290				return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
291			case left.IsZero():
292				return false
293			case right.IsZero():
294				return true
295			case left.Equal(right):
296				return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
297			default:
298				return left.Before(right)
299			}
300		})
301	}
