303	type migrateCheckpointOutcome struct {
304		missingSessions          int
305		compactTranscriptSkipped bool
306	}
307	
308	func migrateOneCheckpoint(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, force bool, fullArtifacts checkpoint.FullSessionArtifactsIndex) (*migratedFullCheckpoint, migrateCheckpointOutcome, error) {
309		var outcome migrateCheckpointOutcome
310	
311		existing, err := v2Store.ReadCommitted(ctx, info.CheckpointID)
312		if err != nil {
313			return nil, outcome, fmt.Errorf("failed to check v2 for checkpoint %s: %w", info.CheckpointID, err)
314		}
315	
316		if existing != nil && !force {
317			// Already in v2. Pack sessions whose /full/* artifacts are missing
318			// (resume an interrupted run) and backfill transcript.jsonl on /main
319			// where it's missing. With nothing to do on either front, return
320			// errAlreadyMigrated so the caller counts it as skipped.
321			fullCheckpoint, err := collectMissingFullCheckpointForPacking(ctx, repo, v1Store, v2Store, info, existing, fullArtifacts)
322			if err != nil && !errors.Is(err, errAlreadyMigrated) {
323				return nil, outcome, err
324			}
325			backfilled, backfillErr := backfillCompactTranscripts(ctx, v1Store, v2Store, info, existing)
326			if errors.Is(backfillErr, errTranscriptNotGeneratable) {
327				outcome.compactTranscriptSkipped = true
328			} else if backfillErr != nil && !errors.Is(backfillErr, errAlreadyMigrated) {
329				return nil, outcome, backfillErr
330			}
331			if fullCheckpoint == nil {
332				if backfilled > 0 {
333					return nil, outcome, nil
334				}
335				return nil, outcome, errAlreadyMigrated
336			}
337			return fullCheckpoint, outcome, nil
338		}
339	
340		if existing != nil && force {
341			if pruneErr := pruneV2CheckpointForForce(ctx, repo, v2Store, info.CheckpointID); pruneErr != nil {
342				return nil, outcome, fmt.Errorf("failed to reset existing v2 checkpoint %s before force migration: %w", info.CheckpointID, pruneErr)
343			}
344		}
345	
346		summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
347		if err != nil {
348			return nil, outcome, fmt.Errorf("failed to read v1 summary: %w", err)
349		}
350		if summary == nil {
351			return nil, outcome, fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
352		}
353	
354		compactFailed := false
355		shouldCopyTaskMetadata := false
356		skippedMissingSessions := 0
357		migratedSessions := 0
358		v1ToV2SessionIdx := make(map[int]int, len(summary.Sessions))
359		fullCheckpoint := &migratedFullCheckpoint{
360			checkpointID: info.CheckpointID,
361		}
362	
363		for sessionIdx := range len(summary.Sessions) {
364			content, skipped, readErr := readV1SessionForMigration(ctx, v1Store, info.CheckpointID, sessionIdx)
365			if skipped {
366				skippedMissingSessions++
367				outcome.missingSessions++
368				continue
369			}
370			if readErr != nil {
371				return nil, outcome, fmt.Errorf("failed to read v1 session %d: %w", sessionIdx, readErr)
372			}
373			if content.Metadata.IsTask {
374				shouldCopyTaskMetadata = true
375			}
376	
377			opts := buildMigrateWriteOpts(content, info, summary.CombinedAttribution)
378	
379			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
380			if compacted != nil {
381				opts.CompactTranscript = compacted
382				opts.CompactTranscriptStart = computeCompactOffset(ctx, content.Transcript, compacted, content.Metadata)
383			} else if len(content.Transcript) > 0 {
384				compactFailed = true
385			}
386	
387			mainOpts := opts
388			mainOpts.Transcript = redact.AlreadyRedacted(nil)
389			v2SessionIdx, writeErr := v2Store.WriteCommittedWithSessionIndex(ctx, mainOpts)
390			if writeErr != nil {
391				return nil, outcome, fmt.Errorf("failed to write v2 session %d: %w", sessionIdx, writeErr)
392			}
393			v1ToV2SessionIdx[sessionIdx] = v2SessionIdx
394			fullCheckpoint.sessions = append(fullCheckpoint.sessions, migratedFullSession{
395				sessionIndex: v2SessionIdx,
396				content:      content,
397			})
398			migratedSessions++
399		}
400	
401		if migratedSessions == 0 {
402			return nil, outcome, fmt.Errorf("%w: v1 metadata lists %d session(s), but no transcript/session content exists for any of them", errNoMigratableSessions, len(summary.Sessions))
403		}
404	
405		if shouldCopyTaskMetadata {
406			taskTrees, taskErr := collectTaskMetadataForMigratedFullGeneration(repo, info.CheckpointID, summary, v1ToV2SessionIdx)
407			if taskErr != nil {
408				logging.Warn(ctx, "failed to copy task metadata to v2",
409					slog.String("checkpoint_id", string(info.CheckpointID)),
410					slog.String("error", taskErr.Error()),
411				)
412			} else {
413				fullCheckpoint.taskTrees = taskTrees
414			}
415		}
416	
417		if compactFailed {
418			outcome.compactTranscriptSkipped = true
419			logging.Warn(ctx, "compact transcript not generated during checkpoint migration",
420				slog.String("checkpoint_id", string(info.CheckpointID)),
421				slog.Int("migrated_sessions", migratedSessions),
422			)
423		}
424		if skippedMissingSessions > 0 {
425			logging.Warn(ctx, "checkpoint migration skipped v1 sessions with missing transcript/session content",
426				slog.String("checkpoint_id", string(info.CheckpointID)),
427				slog.Int("missing_sessions", skippedMissingSessions),
428			)
429		}
430	
431		return fullCheckpoint, outcome, nil
432	}
