434	// generationPacker buffers up to batchSize migrated checkpoints and flushes
435	// them into a single archived /full/<n> ref each time the buffer fills, so
436	// peak heap stays bounded by one batch worth of transcripts instead of
437	// growing with the total v1 list. The next generation number is resolved
438	// lazily on first flush so force-migration prune steps that remove existing
439	// archived refs are visible before we pick the next slot.
440	type generationPacker struct {
441		repo           *git.Repository
442		v2Store        *checkpoint.V2GitStore
443		batchSize      int
444		nextGeneration int
445		numbered       bool
446		pending        []migratedFullCheckpoint
447		flushed        bool
448		// writtenRefs records every /full/<n> ref this packer creates so the
449		// caller can exclude them from the generation-metadata repair pass.
450		writtenRefs []plumbing.ReferenceName
451	}
452	
453	func newGenerationPacker(repo *git.Repository, v2Store *checkpoint.V2GitStore) *generationPacker {
454		batchSize := migrateMaxCheckpointsPerGeneration
455		if batchSize <= 0 {
456			batchSize = checkpoint.DefaultMaxCheckpointsPerGeneration
457		}
458		return &generationPacker{
459			repo:      repo,
460			v2Store:   v2Store,
461			batchSize: batchSize,
462		}
463	}
464	
465	func (p *generationPacker) add(ctx context.Context, cp migratedFullCheckpoint) error {
466		p.pending = append(p.pending, cp)
467		if len(p.pending) >= p.batchSize {
468			return p.flush(ctx)
469		}
470		return nil
471	}
472	
473	func (p *generationPacker) flush(ctx context.Context) error {
474		if len(p.pending) == 0 {
475			return nil
476		}
477		if !p.numbered {
478			next, err := p.v2Store.NextGenerationNumber()
479			if err != nil {
480				return fmt.Errorf("list archived v2 generations: %w", err)
481			}
482			p.nextGeneration = next
483			p.numbered = true
484		}
485		refName := plumbing.ReferenceName(fmt.Sprintf("%s%013d", paths.V2FullRefPrefix, p.nextGeneration))
486		if err := writeMigratedFullGeneration(ctx, p.repo, refName, p.pending); err != nil {
487			return err
488		}
489		p.writtenRefs = append(p.writtenRefs, refName)
490		p.nextGeneration++
491		p.pending = nil
492		p.flushed = true
493		return nil
494	}
495	
496	func (p *generationPacker) finalize(ctx context.Context, ensureEmptyCurrent bool) error {
497		if err := p.flush(ctx); err != nil {
498			return err
499		}
500		if p.flushed && ensureEmptyCurrent {
501			return ensureEmptyV2FullCurrent(ctx, p.repo)
502		}
503		return nil
504	}
505	
506	func writeMigratedFullGeneration(ctx context.Context, repo *git.Repository, refName plumbing.ReferenceName, checkpoints []migratedFullCheckpoint) error {
507		entries := make(map[string]object.TreeEntry)
508	
509		for _, cp := range checkpoints {
510			for _, session := range cp.sessions {
511				if err := writeMigratedFullSessionEntries(ctx, repo, cp, session, entries); err != nil {
512					return fmt.Errorf("write full session entries for checkpoint %s session %d: %w", cp.checkpointID, session.sessionIndex, err)
513				}
514			}
515		}
516	
517		treeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
518		if err != nil {
519			return fmt.Errorf("build migrated generation tree: %w", err)
520		}
521	
522		v2Store := checkpoint.NewV2GitStore(repo, migrateRemoteName)
523		// Reuse the transcripts already in memory rather than walking the tree
524		// we just built — same first/last-event range, no redundant blob reads.
525		gen, found := checkpoint.AggregateTranscriptTimestamps(migratedTranscripts(checkpoints))
526		if !found {
527			var err error
528			gen, found, err = v2Store.ComputeGenerationCheckpointTimestamps(treeHash)
529			if err != nil {
530				return fmt.Errorf("compute checkpoint timestamps: %w", err)
531			}
532		}
533		if !found {
534			gen, found = generationMetadataFromMigratedSessions(checkpoints)
535		}
536		if !found {
537			return fmt.Errorf("no timestamps found for migrated generation %s", refName)
538		}
539	
540		treeHash, err = v2Store.AddGenerationJSONToTree(treeHash, gen)
541		if err != nil {
542			return fmt.Errorf("add generation metadata: %w", err)
543		}
544	
545		commitHash, err := checkpoint.CreateCommit(ctx, repo, treeHash, plumbing.ZeroHash,
546			fmt.Sprintf("Archive migrated generation: %s\n", refName),
547			migrateAuthorName, migrateAuthorEmail)
548		if err != nil {
549			return fmt.Errorf("create migrated generation commit: %w", err)
550		}
551	
552		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
553			return fmt.Errorf("update migrated generation ref %s: %w", refName, err)
554		}
555		return nil
556	}
557	
558	func migratedTranscripts(checkpoints []migratedFullCheckpoint) [][]byte {
559		var transcripts [][]byte
560		for _, cp := range checkpoints {
561			for _, session := range cp.sessions {
562				if len(session.content.Transcript) == 0 {
563					continue
564				}
565				transcripts = append(transcripts, session.content.Transcript)
566			}
567		}
568		return transcripts
569	}
570	
571	func generationMetadataFromMigratedSessions(checkpoints []migratedFullCheckpoint) (checkpoint.GenerationMetadata, bool) {
572		var gen checkpoint.GenerationMetadata
573		found := false
574		for _, cp := range checkpoints {
575			for _, session := range cp.sessions {
576				checkpoint.MergeGenerationTime(&gen, &found, session.content.Metadata.CreatedAt)
577			}
578		}
579		return gen, found
580	}
