582	func writeMigratedFullSessionEntries(ctx context.Context, repo *git.Repository, cp migratedFullCheckpoint, session migratedFullSession, entries map[string]object.TreeEntry) error {
583		sessionPath := fmt.Sprintf("%s/%d/", cp.checkpointID.Path(), session.sessionIndex)
584		transcript := session.content.Transcript
585	
586		chunks, err := agent.ChunkTranscript(ctx, transcript, session.content.Metadata.Agent)
587		if err != nil {
588			return fmt.Errorf("chunk transcript: %w", err)
589		}
590		for i, chunk := range chunks {
591			blobHash, blobErr := checkpoint.CreateBlobFromContent(repo, chunk)
592			if blobErr != nil {
593				return fmt.Errorf("create transcript blob: %w", blobErr)
594			}
595			path := sessionPath + agent.ChunkFileName(paths.V2RawTranscriptFileName, i)
596			entries[path] = object.TreeEntry{
597				Name: path,
598				Mode: filemode.Regular,
599				Hash: blobHash,
600			}
601		}
602	
603		hashPath := sessionPath + paths.V2RawTranscriptHashFileName
604		contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
605		hashBlob, err := checkpoint.CreateBlobFromContent(repo, []byte(contentHash))
606		if err != nil {
607			return fmt.Errorf("create transcript hash blob: %w", err)
608		}
609		entries[hashPath] = object.TreeEntry{
610			Name: hashPath,
611			Mode: filemode.Regular,
612			Hash: hashBlob,
613		}
614	
615		for _, taskTreeHash := range cp.taskTrees[session.sessionIndex] {
616			taskTree, treeErr := repo.TreeObject(taskTreeHash)
617			if treeErr != nil {
618				return fmt.Errorf("read task metadata tree: %w", treeErr)
619			}
620			taskEntries := make(map[string]object.TreeEntry)
621			if flattenErr := checkpoint.FlattenTree(repo, taskTree, sessionPath+"tasks", taskEntries); flattenErr != nil {
622				return fmt.Errorf("flatten task metadata tree: %w", flattenErr)
623			}
624			for path, entry := range taskEntries {
625				if _, exists := entries[path]; exists {
626					continue
627				}
628				entries[path] = entry
629			}
630		}
631	
632		return nil
633	}
