679	func pruneV2CheckpointForForce(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID) error {
680		for _, refName := range []plumbing.ReferenceName{
681			plumbing.ReferenceName(paths.V2MainRefName),
682			plumbing.ReferenceName(paths.V2FullCurrentRefName),
683		} {
684			if err := pruneV2CheckpointRef(ctx, repo, v2Store, refName, cpID); err != nil {
685				return err
686			}
687		}
688	
689		archived, err := v2Store.ListArchivedGenerations()
690		if err != nil {
691			return fmt.Errorf("failed to list archived v2 generations while pruning checkpoint %s: %w", cpID, err)
692		}
