703	func pruneV2CheckpointRef(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, refName plumbing.ReferenceName, cpID id.CheckpointID) error {
704		parentHash, rootTreeHash, err := v2Store.GetRefState(refName)
705		if err != nil {
706			if errors.Is(err, plumbing.ErrReferenceNotFound) {
707				return nil
708			}
709			return fmt.Errorf("failed to get v2 ref state for %s: %w", refName, err)
710		}
711	
712		rootTree, err := repo.TreeObject(rootTreeHash)
713		if err != nil {
714			return fmt.Errorf("failed to read v2 tree for %s: %w", refName, err)
715		}
716		if _, err := rootTree.Tree(cpID.Path()); err != nil {
717			return nil //nolint:nilerr // Checkpoint is absent from this ref, so there is nothing to prune.
718		}
719	
720		shardPrefix := string(cpID[:2])
721		shardSuffix := string(cpID[2:])
722		newRoot, err := pruneCheckpointFromRoot(repo, rootTreeHash, shardPrefix, shardSuffix)
723		if err != nil {
724			return fmt.Errorf("failed to remove checkpoint subtree from %s: %w", refName, err)
725		}
726		if newRoot == rootTreeHash {
727			return nil
728		}
729	
730		commitHash, err := checkpoint.CreateCommit(ctx, repo, newRoot, parentHash,
731			fmt.Sprintf("Reset checkpoint before force migration: %s\n", cpID),
732			migrateAuthorName, migrateAuthorEmail)
733		if err != nil {
734			return fmt.Errorf("failed to create v2 prune commit for %s: %w", refName, err)
735		}
736	
737		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
738			return fmt.Errorf("failed to update ref %s: %w", refName, err)
739		}
740		return nil
741	}
742	
743	func pruneV2ArchivedCheckpointRef(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, refName plumbing.ReferenceName, cpID id.CheckpointID) error {
744		parentHash, rootTreeHash, err := v2Store.GetRefState(refName)
745		if err != nil {
746			if errors.Is(err, plumbing.ErrReferenceNotFound) {
747				return nil
748			}
749			return fmt.Errorf("failed to get v2 ref state for %s: %w", refName, err)
750		}
751	
752		rootTree, err := repo.TreeObject(rootTreeHash)
753		if err != nil {
754			return fmt.Errorf("failed to read v2 tree for %s: %w", refName, err)
755		}
756		if _, err := rootTree.Tree(cpID.Path()); err != nil {
757			return nil //nolint:nilerr // Checkpoint is absent from this ref, so there is nothing to prune.
758		}
759	
760		shardPrefix := string(cpID[:2])
761		shardSuffix := string(cpID[2:])
762		newRoot, err := pruneCheckpointFromRoot(repo, rootTreeHash, shardPrefix, shardSuffix)
763		if err != nil {
764			return fmt.Errorf("failed to remove checkpoint subtree from %s: %w", refName, err)
765		}
766		if newRoot == rootTreeHash {
767			return nil
768		}
769	
770		count, err := v2Store.CountCheckpointsInTree(newRoot)
771		if err != nil {
772			return fmt.Errorf("failed to count checkpoints in pruned %s: %w", refName, err)
773		}
774		if count == 0 {
775			if err := repo.Storer.RemoveReference(refName); err != nil {
776				return fmt.Errorf("failed to remove empty archived v2 generation %s: %w", refName, err)
777			}
778			return nil
779		}
780	
781		newRoot, err = addRecomputedGenerationJSON(v2Store, newRoot)
782		if err != nil {
783			return fmt.Errorf("failed to recompute generation metadata for %s: %w", refName, err)
784		}
785	
786		commitHash, err := checkpoint.CreateCommit(ctx, repo, newRoot, parentHash,
787			fmt.Sprintf("Reset checkpoint before force migration: %s\n", cpID),
788			migrateAuthorName, migrateAuthorEmail)
789		if err != nil {
790			return fmt.Errorf("failed to create v2 prune commit for %s: %w", refName, err)
791		}
792	
793		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
794			return fmt.Errorf("failed to update ref %s: %w", refName, err)
795		}
796		return nil
797	}
