799	func addRecomputedGenerationJSON(v2Store *checkpoint.V2GitStore, treeHash plumbing.Hash) (plumbing.Hash, error) {
800		gen, found, err := v2Store.ComputeGenerationTimestampsFromTrees(treeHash, nil)
801		if err != nil {
802			return plumbing.ZeroHash, fmt.Errorf("compute raw transcript timestamps: %w", err)
803		}
804		if !found {
805			gen, found, err = v2Store.ComputeGenerationCheckpointTimestamps(treeHash)
806			if err != nil {
807				return plumbing.ZeroHash, fmt.Errorf("compute checkpoint timestamps: %w", err)
808			}
809		}
810		if !found {
811			return treeHash, nil
812		}
813	
814		newTreeHash, err := v2Store.AddGenerationJSONToTree(treeHash, gen)
815		if err != nil {
816			return plumbing.ZeroHash, fmt.Errorf("add generation metadata: %w", err)
817		}
818		return newTreeHash, nil
819	}
