821	func pruneCheckpointFromRoot(repo *git.Repository, rootTreeHash plumbing.Hash, shardPrefix, shardSuffix string) (plumbing.Hash, error) {
822		newRoot, err := checkpoint.UpdateSubtree(repo, rootTreeHash,
823			[]string{shardPrefix},
824			nil,
825			checkpoint.UpdateSubtreeOptions{
826				MergeMode:   checkpoint.MergeKeepExisting,
827				DeleteNames: []string{shardSuffix},
828			},
829		)
830		if err != nil {
831			return plumbing.ZeroHash, fmt.Errorf("failed to prune checkpoint from shard: %w", err)
832		}
833		if newRoot == rootTreeHash {
834			return newRoot, nil
835		}
836	
837		newRootTree, err := repo.TreeObject(newRoot)
838		if err != nil {
839			return plumbing.ZeroHash, fmt.Errorf("failed to read pruned root tree: %w", err)
840		}
841		shardTree, err := newRootTree.Tree(shardPrefix)
842		if err != nil {
843			return newRoot, nil //nolint:nilerr // The shard prefix was already absent after pruning.
844		}
845		if len(shardTree.Entries) > 0 {
846			return newRoot, nil
847		}
848	
849		prunedRoot, err := checkpoint.UpdateSubtree(repo, rootTreeHash,
850			nil,
851			nil,
852			checkpoint.UpdateSubtreeOptions{
853				MergeMode:   checkpoint.MergeKeepExisting,
854				DeleteNames: []string{shardPrefix},
855			},
856		)
857		if err != nil {
858			return plumbing.ZeroHash, fmt.Errorf("failed to prune empty shard prefix: %w", err)
859		}
860		return prunedRoot, nil
861	}
