902	func compactTranscriptForStartLine(ctx context.Context, transcript []byte, m checkpoint.CommittedMetadata, startLine int) []byte {
903		if len(transcript) == 0 {
904			return nil
905		}
906		if m.Agent == "" {
907			logging.Warn(ctx, "compact transcript skipped: no agent type in checkpoint metadata",
908				slog.String("checkpoint_id", string(m.CheckpointID)),
909			)
910			return nil
911		}
912	
913		compacted, err := compact.Compact(redact.AlreadyRedacted(transcript), compact.MetadataFields{
914			Agent:      string(m.Agent),
915			CLIVersion: versioninfo.Version,
916			StartLine:  startLine,
917		})
918		if err != nil {
919			logging.Warn(ctx, "compact transcript generation failed during migration",
920				slog.String("checkpoint_id", string(m.CheckpointID)),
921				slog.String("agent", string(m.Agent)),
922				slog.String("error", err.Error()),
923			)
924			return nil
925		}
926		if len(compacted) == 0 {
927			logging.Warn(ctx, "transcript.jsonl generation produced no output",
928				slog.String("checkpoint_id", string(m.CheckpointID)),
929				slog.String("agent", string(m.Agent)),
930				slog.Int("input_bytes", len(transcript)),
931			)
932			return nil
933		}
934		return compacted
935	}
