937	// computeCompactOffset determines the transcript.jsonl line offset for a checkpoint
938	// by comparing a full compact (startLine=0) against the scoped compact. The difference
939	// is the number of compact lines before this checkpoint's data.
940	func computeCompactOffset(ctx context.Context, fullTranscript, fullCompact []byte, m checkpoint.CommittedMetadata) int {
941		startLine := m.GetTranscriptStart()
942		if startLine == 0 || len(fullTranscript) == 0 || m.Agent == "" {
943			return 0
944		}
945	
946		if len(fullCompact) == 0 {
947			return 0
948		}
949	
950		scopedCompact, err := compact.Compact(redact.AlreadyRedacted(fullTranscript), compact.MetadataFields{
951			Agent:      string(m.Agent),
952			CLIVersion: versioninfo.Version,
953			StartLine:  startLine,
954		})
955		if err != nil {
956			logging.Warn(ctx, "compact transcript offset calculation failed during migration",
957				slog.String("checkpoint_id", string(m.CheckpointID)),
958				slog.String("agent", string(m.Agent)),
959				slog.String("error", err.Error()),
960			)
961			return 0
962		}
963		if len(scopedCompact) == 0 {
964			return 0
965		}
966	
967		fullLines := bytes.Count(fullCompact, []byte{'\n'})
968		scopedLines := bytes.Count(scopedCompact, []byte{'\n'})
969		offset := fullLines - scopedLines
970		if offset < 0 {
971			logging.Warn(ctx, "compact transcript offset was negative during migration, defaulting to 0",
972				slog.String("checkpoint_id", string(m.CheckpointID)),
973				slog.Int("full_lines", fullLines),
974				slog.Int("scoped_lines", scopedLines),
975			)
976			return 0
977		}
978		return offset
979	}
