981	func collectTaskMetadataForMigratedFullGeneration(repo *git.Repository, cpID id.CheckpointID, summary *checkpoint.CheckpointSummary, v1ToV2SessionIdx map[int]int) (map[int][]plumbing.Hash, error) {
982		rootTaskV2SessionIdx, attachRootTasks := latestMigratedV2SessionIndex(v1ToV2SessionIdx)
983		return collectTaskMetadataForMigratedFullGenerationWithRootSession(repo, cpID, summary, v1ToV2SessionIdx, rootTaskV2SessionIdx, attachRootTasks)
984	}
985	
986	func collectTaskMetadataForMigratedFullGenerationWithRootSession(
987		repo *git.Repository,
988		cpID id.CheckpointID,
989		summary *checkpoint.CheckpointSummary,
990		v1ToV2SessionIdx map[int]int,
991		rootTaskV2SessionIdx int,
992		attachRootTasks bool,
993	) (map[int][]plumbing.Hash, error) {
994		v1Tree, err := resolveV1CheckpointTree(repo, cpID)
995		if err != nil {
996			return nil, err
997		}
998	
999		taskTrees := make(map[int][]plumbing.Hash)
1000	
1001		// Legacy v1 layout stores task metadata at checkpoint root: <cp>/tasks/<tool-use-id>/...
1002		// Prefer attaching this tree to the latest session in v2.
1003		if rootTasksTree, rootTasksErr := v1Tree.Tree("tasks"); rootTasksErr == nil {
1004			if attachRootTasks {
1005				taskTrees[rootTaskV2SessionIdx] = append(taskTrees[rootTaskV2SessionIdx], rootTasksTree.Hash)
1006			}
1007		}
1008	
1009		for sessionIdx := range len(summary.Sessions) {
1010			sessionDir := strconv.Itoa(sessionIdx)
1011			sessionTree, sessionErr := v1Tree.Tree(sessionDir)
1012			if sessionErr != nil {
1013				continue
1014			}
1015	
1016			tasksTree, tasksErr := sessionTree.Tree("tasks")
1017			if tasksErr != nil {
1018				continue
1019			}
1020	
1021			v2SessionIdx, ok := v1ToV2SessionIdx[sessionIdx]
1022			if !ok {
1023				continue
1024			}
1025			taskTrees[v2SessionIdx] = append(taskTrees[v2SessionIdx], tasksTree.Hash)
1026		}
1027	
1028		return taskTrees, nil
1029	}
1030	
1031	func latestMigratedV2SessionIndex(v1ToV2SessionIdx map[int]int) (int, bool) {
1032		latest := -1
1033		for _, v2SessionIdx := range v1ToV2SessionIdx {
1034			if v2SessionIdx > latest {
1035				latest = v2SessionIdx
1036			}
1037		}
1038		if latest < 0 {
1039			return -1, false
1040		}
1041		return latest, true
1042	}
1043	
1044	func resolveV1CheckpointTree(repo *git.Repository, cpID id.CheckpointID) (*object.Tree, error) {
1045		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1046		ref, err := repo.Reference(refName, true)
1047		if err != nil {
1048			// Try remote tracking branch
1049			remoteRefName := plumbing.NewRemoteReferenceName(migrateRemoteName, paths.MetadataBranchName)
1050			ref, err = repo.Reference(remoteRefName, true)
1051			if err != nil {
1052				return nil, fmt.Errorf("v1 branch not found: %w", err)
1053			}
1054		}
1055	
1056		commit, err := repo.CommitObject(ref.Hash())
1057		if err != nil {
1058			return nil, fmt.Errorf("failed to get v1 commit: %w", err)
1059		}
1060	
1061		rootTree, err := commit.Tree()
1062		if err != nil {
1063			return nil, fmt.Errorf("failed to get v1 tree: %w", err)
1064		}
1065	
1066		cpTree, err := rootTree.Tree(cpID.Path())
1067		if err != nil {
1068			return nil, fmt.Errorf("checkpoint %s not found in v1 tree: %w", cpID, err)
1069		}
1070	
1071		return cpTree, nil
1072	}
1073	
1074	// collectMissingFullCheckpointForPacking returns a migratedFullCheckpoint
1075	// scoped to the sessions that lack /full/* artifacts on this v2 checkpoint,
1076	// reading their content from v1 so the caller can hand it to the same
1077	// generationPacker fresh migrations use. Returns errAlreadyMigrated when
1078	// every session is already packed.
1079	func collectMissingFullCheckpointForPacking(
1080		ctx context.Context,
1081		repo *git.Repository,
1082		v1Store *checkpoint.GitStore,
1083		v2Store *checkpoint.V2GitStore,
1084		info checkpoint.CommittedInfo,
1085		v2Summary *checkpoint.CheckpointSummary,
1086		fullArtifacts checkpoint.FullSessionArtifactsIndex,
1087	) (*migratedFullCheckpoint, error) {
1088		missingSessions, err := collectMissingFullSessionsForPacking(ctx, v2Store, info.CheckpointID, v2Summary, fullArtifacts)
1089		if err != nil {
1090			return nil, err
1091		}
1092		if len(missingSessions) == 0 {
1093			return nil, errAlreadyMigrated
1094		}
1095	
1096		v1Summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
1097		if err != nil {
1098			return nil, fmt.Errorf("failed to read v1 summary while resuming v2 migration: %w", err)
1099		}
1100		if v1Summary == nil {
1101			return nil, fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
1102		}
1103	
1104		v1BySessionID, err := collectV1SessionIndexesForPacking(ctx, v1Store, info.CheckpointID, v1Summary, missingSessions)
1105		if err != nil {
1106			return nil, err
1107		}
1108	
1109		fullCheckpoint := &migratedFullCheckpoint{
1110			checkpointID: info.CheckpointID,
1111		}
1112		v1ToV2SessionIdx := make(map[int]int)
1113	
1114		for _, missingSession := range missingSessions {
1115			v1Session, ok, readErr := readV1SessionForMissingFullArtifact(ctx, v1Store, info.CheckpointID, v1Summary, v1BySessionID, missingSession)
1116			if readErr != nil {
1117				return nil, readErr
1118			}
1119			if !ok {
1120				return nil, fmt.Errorf("failed to find v1 session for v2 session %d while resuming migration", missingSession.sessionIndex)
1121			}
1122	
1123			fullCheckpoint.sessions = append(fullCheckpoint.sessions, migratedFullSession{
1124				sessionIndex: missingSession.sessionIndex,
1125				content:      v1Session.content,
1126			})
1127			v1ToV2SessionIdx[v1Session.sessionIndex] = missingSession.sessionIndex
1128		}
1129	
1130		latestV2SessionIdx := len(v2Summary.Sessions) - 1
1131		taskTrees, taskErr := collectTaskMetadataForMigratedFullGenerationWithRootSession(
1132			repo,
1133			info.CheckpointID,
1134			v1Summary,
1135			v1ToV2SessionIdx,
