1197	// collectV1SessionIndexesForPacking maps each missing session's id to its v1
1198	// session index. Resolving by session_id is necessary because v1/v2 indices
1199	// can drift — v1 sessions without a transcript are skipped on fresh migration.
1200	func collectV1SessionIndexesForPacking(
1201		ctx context.Context,
1202		v1Store *checkpoint.GitStore,
1203		checkpointID id.CheckpointID,
1204		summary *checkpoint.CheckpointSummary,
1205		missingSessions []missingFullSessionForPacking,
1206	) (map[string][]int, error) {
1207		neededSessionIDs := make(map[string]struct{})
1208		for _, session := range missingSessions {
1209			if session.sessionID != "" {
1210				neededSessionIDs[session.sessionID] = struct{}{}
1211			}
1212		}
1213	
1214		bySessionID := make(map[string][]int)
1215		if len(neededSessionIDs) == 0 {
1216			return bySessionID, nil
1217		}
1218	
1219		for sessionIdx := range len(summary.Sessions) {
1220			metadata, err := v1Store.ReadSessionMetadata(ctx, checkpointID, sessionIdx)
1221			if err != nil {
1222				if ctxErr := ctx.Err(); ctxErr != nil {
1223					return nil, fmt.Errorf("context canceled while reading v1 session metadata: %w", ctxErr)
1224				}
1225				continue
1226			}
1227			if _, ok := neededSessionIDs[metadata.SessionID]; ok {
1228				bySessionID[metadata.SessionID] = append(bySessionID[metadata.SessionID], sessionIdx)
1229			}
1230		}
1231	
1232		return bySessionID, nil
1233	}
