1235	func readV1SessionForMissingFullArtifact(
1236		ctx context.Context,
1237		v1Store *checkpoint.GitStore,
1238		checkpointID id.CheckpointID,
1239		summary *checkpoint.CheckpointSummary,
1240		bySessionID map[string][]int,
1241		missingSession missingFullSessionForPacking,
1242	) (v1SessionForPacking, bool, error) {
1243		var triedSessionIndexes map[int]struct{}
1244		if missingSession.sessionID != "" {
1245			indexes := bySessionID[missingSession.sessionID]
1246			triedSessionIndexes = make(map[int]struct{}, len(indexes))
1247			for i := len(indexes) - 1; i >= 0; i-- {
1248				sessionIdx := indexes[i]
1249				triedSessionIndexes[sessionIdx] = struct{}{}
1250				session, found, err := readV1SessionForPacking(ctx, v1Store, checkpointID, sessionIdx)
1251				if err != nil || found {
1252					return session, found, err
1253				}
1254			}
1255		}
1256	
1257		if missingSession.sessionIndex >= len(summary.Sessions) {
1258			return v1SessionForPacking{}, false, nil
1259		}
1260		if _, tried := triedSessionIndexes[missingSession.sessionIndex]; tried {
1261			return v1SessionForPacking{}, false, nil
1262		}
1263		return readV1SessionForPacking(ctx, v1Store, checkpointID, missingSession.sessionIndex)
1264	}
