1296		}
1297	
1298		v1Summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
1299		if err != nil {
1300			return 0, fmt.Errorf("failed to read v1 summary while backfilling compact transcripts: %w", err)
1301		}
1302		if v1Summary == nil {
