1309		}
1310	
1311		backfilled := 0
1312		skippedBackfill := false
1313		var lastAgent string
1314		for _, missingSession := range missingSessions {
1315			v1Session, ok, readErr := readV1SessionForMissingFullArtifact(ctx, v1Store, info.CheckpointID, v1Summary, v1BySessionID, missingSession)
1316			if readErr != nil {
