1344						slog.Int("session_index", missingSession.sessionIndex),
1345					)
1346				}
1347				skippedBackfill = true
1348				continue
1349			}
1350	
1351			updateErr := v2Store.UpdateCommitted(ctx, checkpoint.UpdateCommittedOptions{
1352				CheckpointID:      info.CheckpointID,
1353				SessionID:         content.Metadata.SessionID,
1354				CompactTranscript: compacted,
1355			})
1356			if updateErr != nil {
1357				logging.Warn(ctx, "transcript.jsonl backfill: failed to write to v2",
1358					slog.String("checkpoint_id", string(info.CheckpointID)),
1359					slog.Int("session_index", missingSession.sessionIndex),
1360					slog.String("error", updateErr.Error()),
1361				)
1362				skippedBackfill = true
1363				continue
1364			}
1365	
1366			backfilled++
1367		}
1368	
1369		if backfilled == 0 {
1370			if lastAgent != "" {
1371				return 0, fmt.Errorf("%w: agent %q", errTranscriptNotGeneratable, lastAgent)
1372			}
1373			if skippedNoAgent {
1374				return 0, fmt.Errorf("%w: no agent type in metadata", errTranscriptNotGeneratable)
1375			}
1376			return 0, errTranscriptNotGeneratable
1377		}
1378		if skippedBackfill {
1379			if lastAgent != "" {
1380				return backfilled, fmt.Errorf("%w: agent %q", errTranscriptNotGeneratable, lastAgent)
1381			}
1382			return backfilled, errTranscriptNotGeneratable
1383		}
1384	
1385		return backfilled, nil
1386	}
