544	func v2RefsToPush(ctx context.Context) []plumbing.ReferenceName {
545		repo, err := OpenRepository(ctx)
546		if err != nil {
547			return nil
548		}
549	
550		var refs []plumbing.ReferenceName
551		for _, refName := range []plumbing.ReferenceName{
552			plumbing.ReferenceName(paths.V2MainRefName),
553			plumbing.ReferenceName(paths.V2FullCurrentRefName),
554		} {
555			if _, err := repo.Reference(refName, true); err == nil {
556				refs = append(refs, refName)
557			}
558		}
559	
560		// Push only the latest archived generation (most likely to be newly created).
561		store := checkpoint.NewV2GitStore(repo, "")
562		archived, err := store.ListArchivedGenerations()
563		if err != nil || len(archived) == 0 {
564			return refs
565		}
566		latest := archived[len(archived)-1]
567		refs = append(refs, plumbing.ReferenceName(paths.V2FullRefPrefix+latest))
568	
569		return refs
570	}
